const sendingSettleInDoubt = `-- name: SendingSettleInDoubt :one
UPDATE messages
SET status = $1, sent_at = coalesce(sent_at, $2::timestamptz), claimed_at = NULL, error = '',
    delivered_at = CASE WHEN $1::text = 'delivered' THEN coalesce(delivered_at, $2::timestamptz) ELSE delivered_at END
WHERE id = $3 AND status = 'in_doubt'
RETURNING campaign_id, provider_id, mailbox_provider, variant
`

type SendingSettleInDoubtParams struct {
	Status string    `json:"status"`
	At     time.Time `json:"at"`
	ID     uuid.UUID `json:"id"`
}

type SendingSettleInDoubtRow struct {
	CampaignID      *uuid.UUID `json:"campaignId"`
	ProviderID      *uuid.UUID `json:"providerId"`
	MailboxProvider string     `json:"mailboxProvider"`
	Variant         string     `json:"variant"`
}

// A provider reported an event for a message in doubt: it took the message
// after all. The message counts as sent from the event on.
func (q *Queries) SendingSettleInDoubt(ctx context.Context, arg SendingSettleInDoubtParams) (SendingSettleInDoubtRow, error) {
	row := q.db.QueryRow(ctx, sendingSettleInDoubt, arg.Status, arg.At, arg.ID)
	var i SendingSettleInDoubtRow
	err := row.Scan(
		&i.CampaignID,
		&i.ProviderID,
		&i.MailboxProvider,
		&i.Variant,
	)
	return i, err
}

const sendingSharesOn = `-- name: SendingSharesOn :many

SELECT cr.campaign_id
FROM campaign_routes cr
JOIN campaigns c ON c.id = cr.campaign_id
JOIN campaign_sends s ON s.campaign_id = cr.campaign_id
WHERE cr.provider_id = $1 AND cr.status IN ('pending', 'sending', 'held')
  AND c.status IN ('sending', 'paused') AND c.deleted_at IS NULL AND s.phase = 'sending'
ORDER BY cr.campaign_id
`

// GS-3: one outage path ---------------------------------------------------
// The running sends with an open or held share on a provider: an outage
// the provider health job finds goes through each one's outage path.
func (q *Queries) SendingSharesOn(ctx context.Context, providerID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, sendingSharesOn, providerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var campaign_id uuid.UUID
		if err := rows.Scan(&campaign_id); err != nil {
			return nil, err
		}
		items = append(items, campaign_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

